export function liveTokens(wallet: Wallet, day: number): number {
    return wallet.batches.filter((b) => isLive(b, day)).reduce((sum, b) => sum + b.left, 0);
}

/** Tokens that can be spent on `day` but can no longer be spent on day `day + within`. Does not change the wallet. */
export function expiringSoon(wallet: Wallet, day: number, within: number): number {
    if (within <= 0) {
        return 0;
    }
    return wallet.batches
        .filter((b) => isLive(b, day) && !isLive(b, day + within))
        .reduce((sum, b) => sum + b.left, 0);
}
